package com.bank.txn.model;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Document(collection = "transactions")
public class Transaction {
    @Id
    private String id;
    private String accountId;      // SAV2001 for Rajesh, CUR3001 for Priya
    private String type;           // UPI, CARD, TRANSFER
    private BigDecimal amount;     // money is always BigDecimal
    private LocalDateTime txnDate;

    public Transaction() { }

    public Transaction(String accountId, String type, BigDecimal amount, LocalDateTime txnDate) {
        this.accountId = accountId;
        this.type = type;
        this.amount = amount;
        this.txnDate = txnDate;
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public String getType() { return type; }
    public LocalDateTime getTxnDate() { return txnDate; }
}
