package com.bank.txn.repository;

import com.bank.txn.model.Transaction;
import org.springframework.data.mongodb.repository.MongoRepository;
import org.springframework.data.mongodb.repository.Query;
import java.math.BigDecimal;
import java.util.List;

// Extends both the standard MongoRepository and our custom interface.
// Spring Data wires TransactionRepositoryImpl in automatically by name.
public interface TransactionRepository
        extends MongoRepository<Transaction, String>, TransactionRepositoryCustom {

    // Style 1: derived query method — Spring builds the query from the name.
    List<Transaction> findByAccountIdAndAmountGreaterThan(String accountId, BigDecimal amount);

    // Style 2: raw @Query with positional parameters ?0, ?1.
    @Query("{ 'accountId': ?0, 'type': ?1 }")
    List<Transaction> findByAccountAndType(String accountId, String type);
}
