package com.bank.txn.repository;

import com.bank.txn.dto.MonthlyTotal;
import com.bank.txn.model.Transaction;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.aggregation.Aggregation;
import org.springframework.data.mongodb.core.aggregation.AggregationResults;
import java.util.List;

import static org.springframework.data.mongodb.core.aggregation.Aggregation.*;

// Name MUST be repository name + "Impl" so Spring finds it.
public class TransactionRepositoryImpl implements TransactionRepositoryCustom {

    private final MongoTemplate mongoTemplate;

    public TransactionRepositoryImpl(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    @Override
    public List<MonthlyTotal> monthlyTotals(String accountId) {
        // Pipeline: $match (filter to account) -> $group (by month, sum) -> $sort.
        Aggregation agg = newAggregation(
            match(org.springframework.data.mongodb.core.query.Criteria.where("accountId").is(accountId)),
            project().and("amount").as("amount").andExpression("month(txnDate)").as("month"),
            group("month").sum("amount").as("total"),
            project("total").and("_id").as("month"),
            sort(org.springframework.data.domain.Sort.Direction.DESC, "total")
        );
        AggregationResults<MonthlyTotal> results =
            mongoTemplate.aggregate(agg, "transactions", MonthlyTotal.class);
        return results.getMappedResults();
    }
}
