package com.bank.txn.service;

import com.bank.txn.dto.MonthlyTotal;
import com.bank.txn.model.Transaction;
import com.bank.txn.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class TransactionService {
    private static final Logger log = LoggerFactory.getLogger(TransactionService.class);
    private final TransactionRepository repo;

    public TransactionService(TransactionRepository repo) { this.repo = repo; }

    public List<Transaction> largeTransactions(String accountId, BigDecimal threshold) {
        log.info("Derived query: {} txns above {}", accountId, threshold);
        return repo.findByAccountIdAndAmountGreaterThan(accountId, threshold);
    }

    public List<Transaction> byType(String accountId, String type) {
        log.info("@Query: {} type {}", accountId, type);
        return repo.findByAccountAndType(accountId, type);
    }

    public List<MonthlyTotal> statement(String accountId) {
        log.info("Aggregation: monthly totals for {}", accountId);
        return repo.monthlyTotals(accountId);
    }
}
